contenido:
$ruta = "C:\Users\Usuario\Documents\Mi D\txt\enlaces2026.txt"
$checkpoint = "C:\Users\Usuario\Documents\Mi D\txt\posicion.txt"
$porPantalla = 10

# Leer última línea procesada
$lastLine = 0
if (Test-Path $checkpoint) {
    $lastLine = [int](Get-Content $checkpoint)
}

$contador = 0

Select-String -Path $ruta -Pattern "https?://\S+" -AllMatches | ForEach-Object {

    if ($_.LineNumber -le $lastLine) {
        return
    }

    foreach ($match in $_.Matches.Value) {
        Write-Output $match
        $contador++

        if ($contador -ge $porPantalla) {
            $respuesta = Read-Host "ENTER = continuar | q = salir"

            if ($respuesta -eq "q") {
                Set-Content $checkpoint $_.LineNumber
                exit
            }

            $contador = 0
        }
    }

    # Guardar progreso por línea
    Set-Content $checkpoint $_.LineNumber
}
